{
  "county_id": "HVA05",
  "actions": [
    {
      "action_id": "equal-fast-lane",
      "action": "Offer same-week physician assessment and direct-access diagnostics for red-flag symptoms in public health centres, regardless of employment or insurance.",
      "rationale": "The optimiser picked equal-fast-lane for HVA05, assuming EUR 1,493,400 a year and a central scenario of 39.9 deaths postponed per year (range 5-78.6), while patients waiting over 6 months for specialised care are 54.83 per 10 000 inhabitants against 36 nationally.",
      "owner_role": "Wellbeing services county primary care",
      "indicator": "Waiting time for elective outpatient medical visit (physician) in primary health care exceeds 7 days from assessment of the need for treatment, % appointments kept.",
      "roadmap_measure": "2.5.2"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders in colorectal screening and measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in HVA05 is 75.0% against the 80% target, and the portfolio assigns screening-reminders an assumed cost of EUR 199,120 a year with an expected gain of 1.5-4.5 percentage points.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %.",
      "roadmap_measure": "1.3.1"
    },
    {
      "action_id": "self-sampling",
      "action": "Mail a self-sampling kit with the second reminder to everyone who has not attended cervical screening.",
      "rationale": "Cervical screening participation in HVA05 is 76.3% against the 80% target, and the portfolio assigns self-sampling an assumed cost of EUR 298,680 a year with an expected gain of 1.5-3.67 percentage points.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %.",
      "roadmap_measure": "2.4.4"
    }
  ],
  "evidence_does_not_support": "The evidence does not support a guaranteed mortality effect: the fast-lane estimate is observational from one cancer type, the colorectal reminder gain is borrowed from cervical screening, and the Finnish self-sampling gain is far smaller than the international pooled estimate."
}

